/** GenerateWatchlistCurrentState.php — PHP 7.3+, no external deps. */
date_default_timezone_set('Asia/Jakarta');
function csvAssoc($p){$o=array();$f=fopen($p,'r');$h=fgetcsv($f);if(isset($h[0]))$h[0]=preg_replace('/^\xEF\xBB\xBF/','',$h[0]);while(($r=fgetcsv($f))!==false){$a=array();foreach($h as $i=>$k)$a[$k]=isset($r[$i])?trim($r[$i]):'';$o[]=$a;}fclose($f);return $o;}
$wr=realpath(dirname(__DIR__,3));$rr=realpath(dirname($wr,2));$epochFile=$wr.'/authority/governance/CURRENT_VERIFICATION_EPOCH.json';$verificationEpoch='UNKNOWN';if(is_file($epochFile)){$ep=json_decode(file_get_contents($epochFile),true);if(is_array($ep)&&!empty($ep['verification_epoch']))$verificationEpoch=$ep['verification_epoch'];}$matrix=csvAssoc($wr.'/authority/governance/STRATEGY_TO_IMPLEMENTATION_TRACEABILITY_MATRIX.csv');$deps=csvAssoc($wr.'/development/implementation/WS_DEPENDENCY_REGISTRY.csv');$records=csvAssoc($wr.'/records/WORK_RECORD_REGISTRY.csv');$relationships=csvAssoc($wr.'/records/WORK_RELATIONSHIP_REGISTRY.csv');
