foreach($matrix as $r){if($r['coverage_requirement']!=='REQUIRED'||$r['active']!=='YES')continue;if($r['applicability']==='OPTIONAL_CAPABILITY'){ $optional++; if($r['coverage_status']==='SATISFIED')$optionalSat++; continue;} $required++; if($r['coverage_status']==='SATISFIED')$sat++; elseif($r['coverage_status']==='NOT_ASSESSED')$notAssessed++; else $gaps++;}
$stageStates=array();$stageRows=array();$reg=$wr.'/development/implementation/WS_IMPLEMENTATION_STAGE_REGISTER.md';foreach(file($reg) as $line){if(preg_match('/^\|\s*`(WS-B\d{2})`\s*\|.*?\|\s*`([A-Z0-9_]+)`\s*\|/',$line,$m)){$stageRows[]=$m;$stageStates[$m[2]]=isset($stageStates[$m[2]])?$stageStates[$m[2]]+1:1;}}
$openDeps=0;foreach($deps as $d)if(in_array($d['status'],array('OPEN','WAITING_VERIFIED_DEPENDENCY'),true))$openDeps++;
